-- F1's ledger in the Finance Core (ADR-0089, docs/modules/finance-core.md §3.7): the chart, money
-- accounts, posting rules, monthly periods and the journal in schema `fin`; Finance I's chart, money
-- accounts and journal copied (the chart and money accounts, ids kept) or dropped (the journal, posted
-- again by `pnpm finance:repost-journal`). Generated by drizzle-kit in two steps (the new tables, then the
-- drops), then by hand: the REVOKEs, the append-only and balance triggers, the data section, the drops
-- in dependency order and the assistant's voucher view.
CREATE TABLE "fin"."accounts" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "fin"."accounts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"company_id" bigint NOT NULL,
	"code" text NOT NULL,
	"name" text NOT NULL,
	"kind" text NOT NULL,
	"normal_side" text NOT NULL,
	"control" text DEFAULT 'NONE' NOT NULL,
	"status" text DEFAULT 'ACTIVE' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "fin_accounts_company_id_key" UNIQUE("company_id","id"),
	CONSTRAINT "fin_accounts_company_code_key" UNIQUE("company_id","code"),
	CONSTRAINT "fin_accounts_code" CHECK ("fin"."accounts"."code" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,63}$'),
	CONSTRAINT "fin_accounts_name" CHECK (length(btrim("fin"."accounts"."name")) BETWEEN 1 AND 200),
	CONSTRAINT "fin_accounts_kind" CHECK ("fin"."accounts"."kind" IN ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE')),
	CONSTRAINT "fin_accounts_normal_side" CHECK ("fin"."accounts"."normal_side" IN ('DEBIT', 'CREDIT')),
	CONSTRAINT "fin_accounts_control" CHECK ("fin"."accounts"."control" IN ('NONE', 'RECEIVABLE', 'PAYABLE', 'ADVANCE_RECEIVED', 'ADVANCE_PAID', 'MONEY')),
	CONSTRAINT "fin_accounts_status" CHECK ("fin"."accounts"."status" IN ('ACTIVE', 'INACTIVE'))
);
