-- Nothing in `fin` is deleted or truncated by the application (as 0032 for its tables); the journal
-- and the posting rules are append-only, the chart, money accounts and periods change by status.
REVOKE DELETE, TRUNCATE ON fin.accounts, fin.money_accounts, fin.posting_rules, fin.fiscal_periods,
  fin.journal_entries, fin.journal_lines FROM app;
--> statement-breakpoint
REVOKE UPDATE ON fin.posting_rules, fin.journal_entries, fin.journal_lines FROM app;
--> statement-breakpoint
CREATE TRIGGER posting_rules_append_only BEFORE UPDATE OR DELETE ON fin.posting_rules
  FOR EACH ROW EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
CREATE TRIGGER posting_rules_no_truncate BEFORE TRUNCATE ON fin.posting_rules
  FOR EACH STATEMENT EXECUTE FUNCTION fin.forbid_update_delete();
--> statement-breakpoint
