-- Every entry has at least two lines and Σ debit = Σ credit when the transaction commits, for every
-- role, the migrator included (the core's own copy of 0026's function, so `pg_dump -n fin` is
-- self-contained).
CREATE FUNCTION fin.journal_entry_balanced() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  company bigint;
  entry bigint;
  lines integer;
  difference numeric;
BEGIN
  company := NEW.company_id;
  IF TG_TABLE_NAME = 'journal_entries' THEN
    entry := NEW.id;
  ELSE
    entry := NEW.entry_id;
  END IF;
  SELECT count(*), coalesce(sum(debit) - sum(credit), 0) INTO lines, difference
    FROM fin.journal_lines WHERE company_id = company AND entry_id = entry;
  IF lines < 2 OR difference <> 0 THEN
    RAISE EXCEPTION 'journal entry % is not balanced: % lines, debit - credit = %', entry, lines, difference
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER journal_entries_balanced AFTER INSERT ON fin.journal_entries
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fin.journal_entry_balanced();
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER journal_lines_balanced AFTER INSERT ON fin.journal_lines
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fin.journal_entry_balanced();
--> statement-breakpoint

-- fin_ledger:data:begin
-- No copy of Finance I's journal (ADR-0083 #2): automatic entries are posted again from their
-- documents by `pnpm finance:repost-journal` (development only). A typed entry has no document to
-- post it again from, so a database holding one stops here (export it first; ADR-0089 #8).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.journal_entries WHERE source IN ('MANUAL', 'OPENING')) THEN
    RAISE EXCEPTION 'fin_ledger: % manual or opening journal entries would be lost; they are not posted again',
      (SELECT count(*) FROM public.journal_entries WHERE source IN ('MANUAL', 'OPENING'));
  END IF;
END $$;
--> statement-breakpoint
-- The posting keys and the mapped branches, as the api's boot step makes them (ensureDefaultCompany),
-- because the copies below need them before the next boot.
INSERT INTO fin.posting_keys (company_id, code, required_control, requires_tax_code)
  SELECT c.id, k.code, k.control, k.tax
    FROM fin.companies c
   CROSS JOIN (VALUES
     ('AR', 'RECEIVABLE', false), ('SALES', 'NONE', false), ('SALES_DISCOUNT', 'NONE', false),
     ('SALES_RETURN', 'NONE', false), ('VAT_OUTPUT', 'NONE', true), ('CITY_TAX_OUTPUT', 'NONE', true),
     ('CUSTOMER_ADVANCE', 'ADVANCE_RECEIVED', false), ('CASH', 'MONEY', false), ('BANK', 'MONEY', false),
     ('OTHER_INCOME', 'NONE', false), ('OTHER_EXPENSE', 'NONE', false), ('POS_CASH', 'NONE', false),
     ('CARD_CLEARING', 'NONE', false), ('POS_SALES', 'NONE', false), ('CASH_VARIANCE', 'NONE', false)
   ) AS k (code, control, tax)
   WHERE c.code = 'BO'
  ON CONFLICT DO NOTHING;
--> statement-breakpoint
WITH bo AS (SELECT c.id AS company_id, s.id AS source_id
              FROM fin.companies c JOIN fin.source_systems s ON s.tenant_id = c.tenant_id AND s.code = 'BTO'
             WHERE c.code = 'BO'),
     todo AS MATERIALIZED (
       SELECT b.id AS bto_id, b.code, b.name, bo.company_id, bo.source_id,
              nextval(pg_get_serial_sequence('fin.branches', 'id')) AS branch_id
         FROM public.branches b CROSS JOIN bo
        WHERE b.status = 'ACTIVE'
          AND NOT EXISTS (SELECT 1 FROM fin.branch_refs r
                           WHERE r.company_id = bo.company_id AND r.source_system_id = bo.source_id
                             AND r.external_id = b.id::text)),
     made AS (INSERT INTO fin.branches (id, company_id, code, name)
                OVERRIDING SYSTEM VALUE
                SELECT branch_id, company_id, code, name FROM todo RETURNING id)
INSERT INTO fin.branch_refs (company_id, source_system_id, external_id, branch_id)
  SELECT company_id, source_id, bto_id::text, branch_id FROM todo;
--> statement-breakpoint
-- The chart, with its ids (payments.gl_account_id keeps pointing at the same account): the role's
-- key gives the control, the contra-income accounts of sales returns and discounts are debit-normal.
INSERT INTO fin.accounts (id, company_id, code, name, kind, normal_side, control, status, created_at, updated_at)
  OVERRIDING SYSTEM VALUE
  SELECT g.id, c.id, g.code, g.name, g.kind,
         CASE WHEN g.kind IN ('ASSET', 'EXPENSE') OR g.role IN ('SALES_RETURN', 'SALES_DISCOUNT')
              THEN 'DEBIT' ELSE 'CREDIT' END,
         CASE g.role WHEN 'AR' THEN 'RECEIVABLE' WHEN 'CASH' THEN 'MONEY' WHEN 'BANK' THEN 'MONEY'
                     WHEN 'CUSTOMER_ADVANCE' THEN 'ADVANCE_RECEIVED' ELSE 'NONE' END,
         g.status, g.created_at, g.updated_at
    FROM public.gl_accounts g CROSS JOIN fin.companies c
   WHERE c.code = 'BO';
--> statement-breakpoint
SELECT setval(pg_get_serial_sequence('fin.accounts', 'id'),
              greatest((SELECT max(id) FROM fin.accounts), 1), (SELECT count(*) > 0 FROM fin.accounts));
--> statement-breakpoint
-- Each role becomes the company-default rule of its key, in force from the beginning.
INSERT INTO fin.posting_rules (company_id, posting_key, account_id, effective_from)
  SELECT c.id,
         CASE g.role WHEN 'VAT_PAYABLE' THEN 'VAT_OUTPUT' WHEN 'CITY_TAX_PAYABLE' THEN 'CITY_TAX_OUTPUT'
                     ELSE g.role END,
         g.id, DATE '2000-01-01'
    FROM public.gl_accounts g CROSS JOIN fin.companies c
   WHERE c.code = 'BO' AND g.role IS NOT NULL
   ORDER BY g.id;
--> statement-breakpoint
-- The cash boxes and bank accounts, with their ids (payments, the POS settings and the goods
-- receipts keep them); a branch through its ref, NULL for a closed branch that is not mapped.
INSERT INTO fin.money_accounts (id, company_id, code, name, kind, branch_id, account_id, bank_name,
                                bank_account_no, show_to_customers, status, created_at, updated_at)
  OVERRIDING SYSTEM VALUE
  SELECT m.id, c.id, m.code, m.name, m.kind, r.branch_id, m.gl_account_id, m.bank_name,
         m.bank_account_no, m.show_to_customers, m.status, m.created_at, m.updated_at
    FROM public.money_accounts m
    CROSS JOIN fin.companies c
    LEFT JOIN fin.source_systems s ON s.tenant_id = c.tenant_id AND s.code = 'BTO'
    LEFT JOIN fin.branch_refs r ON r.company_id = c.id AND r.source_system_id = s.id
                               AND r.external_id = m.branch_id::text
   WHERE c.code = 'BO';
--> statement-breakpoint
SELECT setval(pg_get_serial_sequence('fin.money_accounts', 'id'),
              greatest((SELECT max(id) FROM fin.money_accounts), 1),
              (SELECT count(*) > 0 FROM fin.money_accounts));
--> statement-breakpoint
-- The documents' entries go with the old journal; the re-post writes the new ids back.
UPDATE public.invoices SET journal_entry_id = NULL, void_journal_entry_id = NULL
 WHERE journal_entry_id IS NOT NULL OR void_journal_entry_id IS NOT NULL;
--> statement-breakpoint
UPDATE public.credit_notes SET journal_entry_id = NULL WHERE journal_entry_id IS NOT NULL;
--> statement-breakpoint
UPDATE public.payments SET journal_entry_id = NULL, void_journal_entry_id = NULL
 WHERE journal_entry_id IS NOT NULL OR void_journal_entry_id IS NOT NULL;
--> statement-breakpoint
UPDATE public.pos_shifts SET journal_entry_id = NULL, journal_number = NULL
 WHERE journal_entry_id IS NOT NULL OR journal_number IS NOT NULL;
--> statement-breakpoint
DO $$
BEGIN
  IF (SELECT count(*) FROM fin.accounts) <> (SELECT count(*) FROM public.gl_accounts)
  OR (SELECT count(*) FROM fin.money_accounts) <> (SELECT count(*) FROM public.money_accounts)
  OR (SELECT count(*) FROM fin.posting_rules) <> (SELECT count(*) FROM public.gl_accounts WHERE role IS NOT NULL)
  OR EXISTS (SELECT 1 FROM public.gl_accounts g
              WHERE NOT EXISTS (SELECT 1 FROM fin.accounts a
                                 WHERE a.id = g.id AND a.code = g.code AND a.kind = g.kind))
  OR EXISTS (SELECT 1 FROM public.money_accounts m
              WHERE NOT EXISTS (SELECT 1 FROM fin.money_accounts f
                                 WHERE f.id = m.id AND f.code = m.code AND f.account_id = m.gl_account_id))
  OR EXISTS (SELECT 1 FROM public.money_accounts m JOIN public.branches b ON b.id = m.branch_id
              JOIN fin.money_accounts f ON f.id = m.id
              WHERE b.status = 'ACTIVE' AND f.branch_id IS NULL)
  THEN
    RAISE EXCEPTION 'fin_ledger: the copy does not match its sources';
  END IF;
END $$;
