-- The assistant's vouchers (ADR-0060 #10), the same columns over the core's money accounts and
-- chart (one company per installation, ADR-0088: no company filter).
CREATE VIEW ai.payments AS
SELECT p.id, p.number, p.status, p.kind, p.direction, p.money_account_id,
       m.code AS money_account_code, m.name AS money_account_name, m.kind AS money_account_kind,
       br.external_id::bigint AS branch_id, b.name AS branch_name, p.customer_id,
       c.code AS customer_code, c.name AS customer_name, g.code AS gl_account_code,
       g.name AS gl_account_name, p.amount, p.paid_on, p.description, p.reference,
       p.counterparty_name, col.full_name AS collected_by_name, cu.full_name AS created_by_name,
       p.created_at, p.voided_at, p.void_reason
  FROM public.payments p
  JOIN fin.money_accounts m ON m.id = p.money_account_id
  LEFT JOIN fin.source_systems s ON s.code = 'BTO'
  LEFT JOIN fin.branch_refs br ON br.company_id = m.company_id AND br.branch_id = m.branch_id
                              AND br.source_system_id = s.id
  LEFT JOIN public.branches b ON b.id::text = br.external_id
  LEFT JOIN public.customers c ON c.id = p.customer_id
  LEFT JOIN fin.accounts g ON g.id = p.gl_account_id
  LEFT JOIN public.users col ON col.id = p.collected_by
  LEFT JOIN public.users cu ON cu.id = p.created_by;
--> statement-breakpoint
-- app's default privileges (0000_foundation) cover views too: take them back; migrate.ts grants
-- ai_reader after every run.
REVOKE ALL ON ALL TABLES IN SCHEMA ai FROM app;
